import filecmp, os, py_compile, sys, pathlib, json, subprocess, textwrap

t = os.environ["TARGET_DIR"]
o = os.environ["ORIGINAL_DIR"]

# Syntax check modified python files
for d, dirs, files in os.walk(t):
    dirs[:] = [x for x in dirs if x not in (".git", "__pycache__")]
    for f in files:
        if f.endswith(".py"):
            p = os.path.join(d, f)
            rel = os.path.relpath(p, t)
            q = os.path.join(o, rel)
            if not os.path.exists(q) or not filecmp.cmp(p, q, shallow=False):
                try:
                    py_compile.compile(p, doraise=True)
                except Exception as e:
                    print(f"Syntax error in {rel}: {e}")
                    sys.exit(1)
print("Syntax: OK")
